s9 = box('prop', L('Com resoldre un problema de geometria', 'Cómo resolver un problema de geometría', 'How to solve a geometry problem'),
  ol(L(r"<strong>Llig</strong> l'enunciat amb calma i fes un <strong>dibuix</strong> amb totes les dades.", r"<strong>Lee</strong> el enunciado con calma y haz un <strong>dibujo</strong> con todos los datos.", r"<strong>Read</strong> the problem carefully and make a <strong>drawing</strong> with all the data."),
     L(r"Decideix què et demanen: una <strong>longitud</strong> (perímetre, diagonal, altura…) o una <strong>superfície</strong> (àrea).", r"Decide qué te piden: una <strong>longitud</strong> (perímetro, diagonal, altura…) o una <strong>superficie</strong> (área).", r"Decide what you're asked for: a <strong>length</strong> (perimeter, diagonal, height…) or a <strong>surface</strong> (area)."),
     L(r"Si et falta una longitud, busca un <strong>triangle rectangle</strong> i aplica Pitàgores.", r"Si te falta una longitud, busca un <strong>triángulo rectángulo</strong> y aplica Pitágoras.", r"If a length is missing, look for a <strong>right triangle</strong> and use Pythagoras."),
     L(r"Passa totes les dades a la <strong>mateixa unitat</strong> abans de calcular.", r"Pasa todos los datos a la <strong>misma unidad</strong> antes de calcular.", r"Convert all the data to the <strong>same unit</strong> before calculating."),
     L(r"Calcula, <strong>comprova</strong> que el resultat té sentit i respon amb una frase i les unitats.", r"Calcula, <strong>comprueba</strong> que el resultado tiene sentido y responde con una frase y las unidades.", r"Calculate, <strong>check</strong> the answer makes sense and reply with a sentence and the units."))
  + tbl([L('Si el problema parla de…', 'Si el problema habla de…', 'If the problem talks about…'), L('Calculem', 'Calculamos', 'We find'), L('Unitats', 'Unidades', 'Units')],
        [[L('tanca, sòcol, marc, cinta, vora, voltes a una pista', 'valla, zócalo, marco, cinta, borde, vueltas a una pista', 'fence, skirting, frame, ribbon, edging, laps of a track'), L('el <strong>perímetre</strong>', 'el <strong>perímetro</strong>', 'the <strong>perimeter</strong>'), 'm, cm…'],
         [L('pintar, gespa, rajoles, moqueta, tela, terreny', 'pintar, césped, baldosas, moqueta, tela, terreno', 'painting, lawn, tiles, carpet, fabric, land'), L("l'<strong>àrea</strong>", 'el <strong>área</strong>', 'the <strong>area</strong>'), 'm², cm², ha…'],
         [L('escala, diagonal, distància en línia recta, altura', 'escalera, diagonal, distancia en línea recta, altura', 'ladder, diagonal, straight-line distance, height'), L('un costat amb <strong>Pitàgores</strong>', 'un lado con <strong>Pitágoras</strong>', 'a side with <strong>Pythagoras</strong>'), 'm, cm…']])
  + note(r"Quan calcules quantes rajoles, pots de pintura o rotlles calen, <strong>arrodoneix cap amunt</strong>: si en fan falta 233,3, n'has de comprar 234.",
         r"Cuando calcules cuántas baldosas, botes de pintura o rollos hacen falta, <strong>redondea hacia arriba</strong>: si hacen falta 233,3, tienes que comprar 234.",
         r"When you work out how many tiles, tins of paint or rolls you need, <strong>round up</strong>: if you need 233.3, you have to buy 234.", '⚠️')
  + drill('prob', 'Entrena: problemes amb enunciat', 'Entrena: problemas con enunciado', 'Train: word problems'))

PAR = G([('poly', [(0, 0), (40, 0), (25, 20), (0, 20)], 'lawn'), ('seg', (25, 0), (25, 20), 'd'), ('ra', (0, 0), (1, 0), (0, 1)), ('ra', (25, 0), (40, 0), (25, 20)),
         T_((20, 0), '40 m', dy=15), T_((12.5, 20), '25 m', dy=-7), T_((0, 10), '20 m', dx=-8, a='end'), T_((32.5, 0), '15', dy=-6), T_(off((40, 0), (25, 20), -2.5), 'c', a='start', cls='hy')], W=220)
KITE = G([('poly', [(-40, 0), (0, 30), (40, 0), (0, -30)], 'gf'), ('seg', (-40, 0), (40, 0), 'd'), ('seg', (0, -30), (0, 30), 'd'), ('poly', [(0, 0), (40, 0), (0, 30)], 'tr'), ('ra', (0, 0), (40, 0), (0, 30)),
          T_((20, 0), '40', dy=15), T_((0, 15), '30', dx=-6, a='end'), T_(off((40, 0), (0, 30), -4), 'l', cls='hy', a='start')], W=200)
WALL = G([('poly', [(0, 0), (4.5, 0), (4.5, 2.6), (0, 2.6)], 'gf'), ('poly', [(0.6, 0), (1.4, 0), (1.4, 2), (0.6, 2)], 'hole'), ('poly', [(0.6, 0), (1.4, 0), (1.4, 2), (0.6, 2)], 'frame'),
          T_((2.25, 0), '4,5 m', dy=15), T_((4.5, 1.3), '2,6 m', dx=8, a='start'), T_((1, 2), '0,8 m', dy=-7), T_((1.4, 1), '2 m', dx=6, a='start')], W=210)
POOL = G([('circ', (0, 0), 4, 'sh'), ('circ', (0, 0), 3, 'hole'), ('circ', (0, 0), 3, 'gc'), ('circ', (0, 0), 4, 'gc'), ('dot', (0, 0)), ('seg', (0, 0), (3, 0), 'd'), ('seg', (3, 0), (4, 0), 'hl'),
          T_((1.5, 0), '3 m', dy=-6), T_((3.5, 0), '1 m', dy=15)], W=170)
PARK = G([('poly', [(0, 0), (80, 0), (80, 80), (0, 80)], 'lawn'), ('seg', (0, 0), (80, 80), 'hl'), ('seg', (0, 0), (80, 0), 'd'), ('seg', (80, 0), (80, 80), 'd'), ('dot', (0, 0)), ('dot', (80, 80)),
          T_((0, 0), 'A', dx=-8, dy=4, a='end'), T_((80, 80), 'B', dx=8, a='start'), T_((40, 0), '80 m', dy=15), T_((80, 40), '80 m', dx=8, a='start'), T_(off((0, 0), (80, 80), 8), 'd', cls='hy')], W=180)

s9 += levels(
 [prob(L(r"Volem tancar un camp rectangular de 45 m de llarg i 28 m d'ample. Quants metres de tanca necessitem? Si el metre de tanca costa 3,50 €, quant costarà?", r"Queremos vallar un campo rectangular de 45 m de largo y 28 m de ancho. ¿Cuántos metros de valla necesitamos? Si el metro de valla cuesta 3,50 €, ¿cuánto costará?", r"We want to fence a rectangular field 45 m long and 28 m wide. How many metres of fence do we need? If fencing costs €3.50 per metre, how much will it cost?"),
       P(r"La tanca va pel contorn: és el <strong>perímetre</strong>.", r"La valla va por el contorno: es el <strong>perímetro</strong>.", r"The fence goes round the edge: it's the <strong>perimeter</strong>."),
       D(r"P=2\cdot45+2\cdot28=\boxed{146\ \text{m}}\qquad 146\cdot3{,}50=\boxed{511\ \text{€}}")),
  prob(L(r"Hem de pintar una paret de 4,5 m × 2,6 m que té una porta de 0,8 m × 2 m. Amb 1 litre de pintura es pinten 10 m². Quants litres necessitem?", r"Tenemos que pintar una pared de 4,5 m × 2,6 m que tiene una puerta de 0,8 m × 2 m. Con 1 litro de pintura se pintan 10 m². ¿Cuántos litros necesitamos?", r"We have to paint a 4.5 m × 2.6 m wall with a 0.8 m × 2 m door in it. 1 litre of paint covers 10 m². How many litres do we need?") + figs(WALL),
       P(r"Pintem una <strong>superfície</strong>: calculem l'àrea de la paret i li llevem la de la porta.", r"Pintamos una <strong>superficie</strong>: calculamos el área de la pared y le quitamos la de la puerta.", r"We paint a <strong>surface</strong>: find the wall's area and subtract the door's."),
       D(r"A=4{,}5\cdot2{,}6-0{,}8\cdot2=11{,}7-1{,}6=10{,}1\ \text{m}^2\qquad \frac{10{,}1}{10}=\boxed{1{,}01\ \text{L}}"))],
 [prob(L(r"Els bombers han de pujar per una escala de 6,5 m fins a una finestra que està a 6 m d'altura. A quina distància de la paret han de posar el peu de l'escala?", r"Los bomberos tienen que subir por una escalera de 6,5 m hasta una ventana que está a 6 m de altura. ¿A qué distancia de la pared tienen que poner el pie de la escalera?", r"Firefighters have to climb a 6.5 m ladder up to a window 6 m high. How far from the wall must they put the foot of the ladder?"),
       P(r"L'escala és la hipotenusa; l'altura de la finestra i la distància a la paret són els catets:", r"La escalera es la hipotenusa; la altura de la ventana y la distancia a la pared son los catetos:", r"The ladder is the hypotenuse; the window's height and the distance to the wall are the legs:"),
       D(r"x=\sqrt{6{,}5^2-6^2}=\sqrt{42{,}25-36}=\sqrt{6{,}25}=\boxed{2{,}5\ \text{m}}")),
  prob(L(r"Una parcel·la té forma de trapezi rectangle, amb bases de 40 m i 25 m i 20 m d'amplària. a) Si el metre quadrat val 120 €, quant costa la parcel·la? b) Quants metres de tanca calen per a envoltar-la?", r"Una parcela tiene forma de trapecio rectángulo, con bases de 40 m y 25 m y 20 m de anchura. a) Si el metro cuadrado vale 120 €, ¿cuánto cuesta la parcela? b) ¿Cuántos metros de valla hacen falta para rodearla?", r"A plot of land is a right trapezium with bases of 40 m and 25 m and a width of 20 m. a) If land costs €120 per square metre, how much is the plot? b) How many metres of fence are needed to go round it?") + figs(PAR),
       D(r"\text{a) }A=\frac{(40+25)\cdot20}{2}=650\ \text{m}^2\qquad 650\cdot120=\boxed{78\,000\ \text{€}}"),
       P(r"b) Ens falta el costat oblic \(c\): és la hipotenusa d'un triangle de catets \(40-25=15\) i 20.", r"b) Nos falta el lado oblicuo \(c\): es la hipotenusa de un triángulo de catetos \(40-25=15\) y 20.", r"b) We need the slanted side \(c\): it's the hypotenuse of a triangle with legs \(40-25=15\) and 20."),
       D(r"c=\sqrt{15^2+20^2}=\sqrt{625}=25\qquad P=40+25+20+25=\boxed{110\ \text{m}}")),
  prob(L(r"Un estel té forma de rombe, amb diagonals de 80 cm i 60 cm. Quanta tela fa falta per a fer-lo? Quanta cinta cal per a posar-li tota la vora?", r"Una cometa tiene forma de rombo, con diagonales de 80 cm y 60 cm. ¿Cuánta tela hace falta para hacerla? ¿Cuánta cinta hace falta para ponerle todo el borde?", r"A kite is a rhombus with diagonals of 80 cm and 60 cm. How much fabric is needed to make it? How much ribbon is needed for its whole edge?") + figs(KITE),
       D(r"A=\frac{80\cdot60}{2}=\boxed{2400\ \text{cm}^2}"),
       D(r"l=\sqrt{40^2+30^2}=\sqrt{2500}=50\ \text{cm}\qquad P=4\cdot50=\boxed{200\ \text{cm}}"))],
 [prob(L(r"Al voltant d'una piscina circular de 6 m de diàmetre volem fer una vorera d'1 m d'amplària amb rajoles quadrades de 20 cm de costat. Quantes rajoles necessitarem, com a mínim?", r"Alrededor de una piscina circular de 6 m de diámetro queremos hacer una acera de 1 m de ancho con baldosas cuadradas de 20 cm de lado. ¿Cuántas baldosas necesitaremos, como mínimo?", r"Around a round pool 6 m across we want to lay a 1 m wide path with square tiles with 20 cm sides. How many tiles will we need, at least?") + figs(POOL),
       P(r"La vorera és una <strong>corona circular</strong> de radis \(R=3+1=4\) m i \(r=3\) m:", r"La acera es una <strong>corona circular</strong> de radios \(R=3+1=4\) m y \(r=3\) m:", r"The path is an <strong>annulus</strong> with radii \(R=3+1=4\) m and \(r=3\) m:"),
       D(r"A=\pi\left(4^2-3^2\right)=7\pi\approx21{,}99\ \text{m}^2\qquad A_{\text{%s}}=0{,}2^2=0{,}04\ \text{m}^2" % Lt('rajola', 'baldosa', 'tile')),
       D(r"\frac{21{,}99}{0{,}04}\approx549{,}8\ \Rightarrow\ \boxed{550\ \text{%s}}" % Lt('rajoles', 'baldosas', 'tiles'))),
  prob(L(r"Un parc és un quadrat de 80 m de costat. Per a anar d'una cantonada \(A\) a la cantonada oposada \(B\), la Marta el travessa en diagonal en lloc de fer la volta per dos costats. Quants metres s'estalvia?", r"Un parque es un cuadrado de 80 m de lado. Para ir de una esquina \(A\) a la esquina opuesta \(B\), Marta lo cruza en diagonal en lugar de dar la vuelta por dos lados. ¿Cuántos metros se ahorra?", r"A park is a square with 80 m sides. To get from corner \(A\) to the opposite corner \(B\), Marta crosses it diagonally instead of walking along two sides. How many metres does she save?") + figs(PARK),
       D(r"d=\sqrt{80^2+80^2}=\sqrt{12\,800}\approx113{,}14\ \text{m}"),
       D(r"160-113{,}14=\boxed{46{,}86\ \text{m}}")),
  prob(L(r"Un televisor de 55 polzades té una pantalla de proporció 16:9 (l'amplària i l'altura són proporcionals a 16 i 9). La mida en polzades és la de la diagonal, i 1 polzada són 2,54 cm. Quant mesura la pantalla?", r"Un televisor de 55 pulgadas tiene una pantalla de proporción 16:9 (el ancho y el alto son proporcionales a 16 y 9). La medida en pulgadas es la de la diagonal, y 1 pulgada son 2,54 cm. ¿Cuánto mide la pantalla?", r"A 55-inch TV has a 16:9 screen (width and height are proportional to 16 and 9). The size in inches is the diagonal, and 1 inch is 2.54 cm. How big is the screen?"),
       D(r"d=55\cdot2{,}54=139{,}7\ \text{cm}"),
       P(r"Si l'amplària és \(16k\) i l'altura \(9k\):", r"Si el ancho es \(16k\) y el alto \(9k\):", r"If the width is \(16k\) and the height \(9k\):"),
       D(r"(16k)^2+(9k)^2=139{,}7^2\ \Rightarrow\ 337k^2=19\,516{,}09\ \Rightarrow\ k\approx7{,}61"),
       D(r"16k\approx\boxed{121{,}8\ \text{cm}}\qquad 9k\approx\boxed{68{,}5\ \text{cm}}"))])
ck(2 * 45 + 2 * 28, 146); ck(146 * R(35, 10), 511); ck(R(45, 10) * R(26, 10) - R(8, 10) * 2, R(101, 10)); ck(R(101, 100), 1.01)
ck(leg(R(65, 10), 6), R(5, 2)); ck(R(65 * 20, 2), 650); ck(650 * 120, 78000); ck(hyp(15, 20), 25); ck(40 + 25 + 20 + 25, 110)
ck(R(80 * 60, 2), 2400); ck(hyp(40, 30), 50)
ck(7 * pi, 21.99, 2); ck(7 * pi / R(4, 100), 549.8, 1); assert math.ceil(7 * math.pi / 0.04) == 550
ck(hyp(80, 80), 113.14, 2); ck(160 - hyp(80, 80), 46.86, 2)
k_ = R(1397, 10) / S(337); ck(k_, 7.61, 2); ck(16 * k_, 121.8, 1); ck(9 * k_, 68.5, 1); ck(R(1397, 10) ** 2, 19516.09)

s9 += practice([
  ('★', L(r"a) Un sòcol envolta una habitació rectangular de 5 m × 3,6 m que té una porta de 0,9 m d'amplària. Quants metres de sòcol calen? b) Una catifa circular fa 2 m de diàmetre. Quina superfície ocupa?", r"a) Un zócalo rodea una habitación rectangular de 5 m × 3,6 m que tiene una puerta de 0,9 m de ancho. ¿Cuántos metros de zócalo hacen falta? b) Una alfombra circular mide 2 m de diámetro. ¿Qué superficie ocupa?", r"a) Skirting board goes round a 5 m × 3.6 m rectangular room with a 0.9 m wide door. How many metres of skirting are needed? b) A round rug is 2 m across. What area does it cover?")),
  ('★★', L(r"c) Un camp de gespa rectangular de 60 m × 40 m es rega amb un aspersor que cobreix 25 m² per minut. Quant de temps tarda a regar-lo tot? d) Una rampa puja 1,2 m d'altura en una distància horitzontal de 5 m. Quant mesura la rampa?", r"c) Un campo de césped rectangular de 60 m × 40 m se riega con un aspersor que cubre 25 m² por minuto. ¿Cuánto tiempo tarda en regarlo todo? d) Una rampa sube 1,2 m de altura en una distancia horizontal de 5 m. ¿Cuánto mide la rampa?", r"c) A 60 m × 40 m rectangular lawn is watered by a sprinkler covering 25 m² per minute. How long does it take to water it all? d) A ramp rises 1.2 m over a horizontal distance of 5 m. How long is the ramp?")),
  ('★★★', L(r"e) Una pista d'atletisme té dues rectes de 100 m i dues corbes que són semicircumferències de 32 m de radi. Quants metres fa una volta? Quantes voltes completes cal fer per a córrer 5 km?", r"e) Una pista de atletismo tiene dos rectas de 100 m y dos curvas que son semicircunferencias de 32 m de radio. ¿Cuántos metros mide una vuelta? ¿Cuántas vueltas completas hay que dar para correr 5 km?", r"e) A running track has two 100 m straights and two bends that are semicircles with a 32 m radius. How long is one lap? How many full laps do you need to run 5 km?"))],
  P(r"a) \(2\cdot5+2\cdot3{,}6-0{,}9=16{,}3\) m. b) \(\pi\cdot1^2\approx3{,}14\) m². c) \(\tfrac{2400}{25}=96\) min (1 h 36 min). d) \(\sqrt{5^2+1{,}2^2}=\sqrt{26{,}44}\approx5{,}14\) m. e) \(200+2\pi\cdot32\approx401{,}06\) m; \(\tfrac{5000}{401{,}06}\approx12{,}47\): 12 voltes completes no arriben, en calen 13.",
    r"a) \(2\cdot5+2\cdot3{,}6-0{,}9=16{,}3\) m. b) \(\pi\cdot1^2\approx3{,}14\) m². c) \(\tfrac{2400}{25}=96\) min (1 h 36 min). d) \(\sqrt{5^2+1{,}2^2}=\sqrt{26{,}44}\approx5{,}14\) m. e) \(200+2\pi\cdot32\approx401{,}06\) m; \(\tfrac{5000}{401{,}06}\approx12{,}47\): con 12 vueltas completas no se llega, hacen falta 13.",
    r"a) \(2\cdot5+2\cdot3.6-0.9=16.3\) m. b) \(\pi\cdot1^2\approx3.14\) m². c) \(\tfrac{2400}{25}=96\) min (1 h 36 min). d) \(\sqrt{5^2+1.2^2}=\sqrt{26.44}\approx5.14\) m. e) \(200+2\pi\cdot32\approx401.06\) m; \(\tfrac{5000}{401.06}\approx12.47\): 12 full laps aren't enough, you need 13."))
ck(10 + R(72, 10) - R(9, 10), 16.3); ck(pi, 3.14, 2); ck(R(2400, 25), 96); ck(hyp(5, R(12, 10)), 5.14, 2); ck(200 + 64 * pi, 401.06, 2); ck(5000 / (200 + 64 * pi), 12.47, 2)
